/* prog48_sorted_linked_list.c
 *
 * The original program reads up to 64 signed decimal numbers from the command
 * line, stores them in a singly‑linked list that is kept sorted in ascending
 * order, and finally prints the list on a single line separated by spaces.
 * If no numbers are supplied the program prints the word “EMPTY”.
 *
 * The binary was heavily obfuscated, but the underlying algorithm is a classic
 * sorted‑insert linked list.  The reconstruction below follows the same logic
 * while using clear, idiomatic C.
 */

#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

#define MAX_ELEMS 64          /* maximum number of values the program accepts */

static long   value[MAX_ELEMS];   /* stored numbers */
static int    next[MAX_ELEMS];    /* link to the next element (index) */
static int    head = -1;          /* index of the first element, -1 = empty */
static int    used = 0;           /* number of elements currently stored */

/* Insert a new value into the list while keeping it sorted (ascending). */
static void sorted_insert(long v)
{
    int idx = used;               /* index of the new node */
    value[idx] = v;
    next[idx]  = -1;              /* will be set correctly below */

    /* Empty list – new node becomes the head */
    if (head == -1) {
        head = idx;
        return;
    }

    /* If the new value is smaller than the current head, insert at front */
    if (value[head] > v) {
        next[idx] = head;
        head = idx;
        return;
    }

    /* Otherwise walk the list to find the insertion point */
    int cur = head;
    while (next[cur] != -1 && value[next[cur]] <= v) {
        cur = next[cur];
    }

    /* Insert after ‘cur’ */
    next[idx] = next[cur];
    next[cur] = idx;
}

/* Print the list in the required format. */
static void print_list(void)
{
    if (head == -1) {
        puts("EMPTY");
        return;
    }

    int cur = head;
    int first = 1;
    while (cur != -1) {
        if (!first) putchar(' ');
        printf("%ld", value[cur]);
        first = 0;
        cur = next[cur];
    }
    putchar('\n');
}

/* ---------------------------------------------------------------------- */
int main(int argc, char *argv[])
{
    /* The original program accepted at most 64 numbers.  Excess arguments are
       simply ignored – this matches the behaviour of the decompiled binary. */
    for (int i = 1; i < argc && used < MAX_ELEMS; ++i) {
        char *endptr = NULL;
        long v = strtol(argv[i], &endptr, 10);
        (void)endptr;               /* the original code ignored conversion errors */
        sorted_insert(v);
        ++used;
    }

    print_list();
    return 0;
}
